import { Injectable } from '@angular/core';
import { BADGE_VARIANTS, BUTTON_VARIANTS, ICON_SETS, INPUT_VARIANTS, type IconSetType } from '../interfaces/variables.interface';

@Injectable(
  {
    providedIn: 'root'
  }
)
export class VariablesService {

  private readonly iconSets = ICON_SETS;

  // Backward-compatible aliases (keep existing keys used across templates/components)
  readonly comnicn: Record<string, string> = this.iconSets.comnicn;
  readonly adminicn: Record<string, string> = this.iconSets.adminicn;
  readonly indicn: Record<string, string> = this.iconSets.indicn;
  readonly real_icn: Record<string, string> = this.iconSets.real_icn;
  readonly myfileicn: Record<string, string> = this.iconSets.myfileicn;
  readonly toolicn: Record<string, string> = this.iconSets.toolicn;
  readonly extra: Record<string, string> = this.iconSets.extra;
  readonly present: Record<string, string> = this.iconSets.present;

  // Clearer names for new code (prefer these going forward)
  readonly commonIcons: Record<string, string> = this.iconSets.comnicn;
  readonly adminIcons: Record<string, string> = this.iconSets.adminicn;
  readonly indicatorIcons: Record<string, string> = this.iconSets.indicn;
  readonly realtimeIcons: Record<string, string> = this.iconSets.real_icn;
  readonly myFilesIcons: Record<string, string> = this.iconSets.myfileicn;
  readonly toolIcons: Record<string, string> = this.iconSets.toolicn;
  readonly extraIcons: Record<string, string> = this.iconSets.extra;
  readonly presentationIcons: Record<string, string> = this.iconSets.present;

  private isIconSetType(type: string): type is IconSetType {
    return type in this.iconSets;
  }

  getIconUnicode(name: string, type: string): string {
    if (!this.isIconSetType(type)) {
      return '';
    }
    return this.iconSets[type][name] ?? '';
  }


  // Backward-compatible variant maps (existing property names)
  readonly btnvarnt = BUTTON_VARIANTS;
  readonly badgevarnt = BADGE_VARIANTS;
  readonly inputvarnts = INPUT_VARIANTS;

  // Clearer names for new code
  readonly buttonVariants = BUTTON_VARIANTS;
  readonly badgeVariants = BADGE_VARIANTS;
  readonly inputVariants = INPUT_VARIANTS;

  constructor() {}

}
